focal_methods:
public static DateTimeZone getDefault() {
        DateTimeZone zone = cDefault.get();
        if (zone == null) {
            try {
                try {
                    String id = System.getProperty("org.joda.time.DateTimeZone.Timezone");
                    if (id != null) {  // null check avoids stack overflow
                        zone = forID(id);
                    }
                } catch (RuntimeException ex) {
                    // ignored
                }
                if (zone == null) {
                    zone = forTimeZone(TimeZone.getDefault());
                }
            } catch (IllegalArgumentException ex) {
                // ignored
            }
            if (zone == null) {
                zone = UTC;
            }
            if (!cDefault.compareAndSet(null, zone)) {
                zone = cDefault.get();
            }
        }
        return zone;
    }

public static void setDefault(DateTimeZone zone) throws SecurityException {
        SecurityManager sm = System.getSecurityManager();
        if (sm != null) {
            sm.checkPermission(new JodaTimePermission("DateTimeZone.setDefault"));
        }
        if (zone == null) {
            throw new IllegalArgumentException("The datetime zone must not be null");
        }
        cDefault.set(zone);
    }

test_prefix:
public void testForID_String_oe() {
        assertEquals(DateTimeZone.getDefault(),DateTimeZone.forID((String)null));

        DateTimeZone zone = DateTimeZone.forID("Europe/London");
        assertEquals("Europe/London",zone.getID());

        zone = DateTimeZone.forID("UTC");
        assertSame(DateTimeZone.UTC,zone);

        zone = DateTimeZone.forID("+00:00");
        assertSame(DateTimeZone.UTC,zone);

        zone = DateTimeZone.forID("+00");
        assertSame(DateTimeZone.UTC,zone);

        zone = DateTimeZone.forID("+01:23");
        assertEquals("+01:23",zone.getID());
        assertEquals(DateTimeConstants.MILLIS_PER_HOUR +(23L * DateTimeConstants.MILLIS_PER_MINUTE),zone.getOffset(TEST_TIME_SUMMER));

        zone = DateTimeZone.forID("-02:00");
        assertEquals("-02:00",zone.getID());
        assertEquals((-2L * DateTimeConstants.MILLIS_PER_HOUR),zone.getOffset(TEST_TIME_SUMMER));

        zone = DateTimeZone.forID("-07:05:34.0");
        assertEquals("-07:05:34",zone.getID());
        assertEquals((-7L * DateTimeConstants.MILLIS_PER_HOUR)+(-5L * DateTimeConstants.MILLIS_PER_MINUTE)+(-34L * DateTimeConstants.MILLIS_PER_SECOND),zone.getOffset(TEST_TIME_SUMMER));

        try {
            DateTimeZone.forID("SST");
            fail();
        } catch (IllegalArgumentException ex) {}
        try {
            DateTimeZone.forID("europe/london");
            fail();
        } catch (IllegalArgumentException ex) {}
        try {
            DateTimeZone.forID("Europe/UK");
            fail();
        } catch (IllegalArgumentException ex) {}
        try {
            DateTimeZone.forID("+");
            fail();
        } catch (IllegalArgumentException ex) {}
        try {
            DateTimeZone.forID("+0");
            fail();
        } catch (IllegalArgumentException ex) {}
    }

focal_methods:
@FromString
    public static DateTimeZone forID(String id) {
        if (id == null) {
            return getDefault();
        }
        if (id.equals("UTC")) {
            return DateTimeZone.UTC;
        }
        DateTimeZone zone = getProvider().getZone(id);
        if (zone != null) {
            return zone;
        }
        if (id.startsWith("+") || id.startsWith("-")) {
            int offset = parseOffset(id);
            if (offset == 0L) {
                return DateTimeZone.UTC;
            } else {
                id = printOffset(offset);
                return fixedOffsetZone(id, offset);
            }
        }
        throw new IllegalArgumentException("The datetime zone id '" + id + "' is not recognised");
    }

@ToString
    public final String getID() {
        return iID;
    }

public final int getOffset(ReadableInstant instant) {
        if (instant == null) {
            return getOffset(DateTimeUtils.currentTimeMillis());
        }
        return getOffset(instant.getMillis());
    }

